package com.andye.warmod.radar.station.network;import com.andye.warmod.block.RadarStationStructure;import com.andye.warmod.block.entity.RadarStationBlockEntity;import com.andye.warmod.radar.station.*;import java.util.*;import net.fabricmc.fabric.api.networking.v1.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.phys.Vec3;public final class RadarStationNetworking {private static final Map<UUID,Viewer>VIEWERS=new HashMap<>();private static boolean registered;private RadarStationNetworking(){}public static void register(){if(registered)return;PayloadTypeRegistry.clientboundPlay().register(ClientboundOpenRadarStationPayload.TYPE,ClientboundOpenRadarStationPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundRadarStationObservationPayload.TYPE,ClientboundRadarStationObservationPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundRadarStationStatePayload.TYPE,ClientboundRadarStationStatePayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundCloseRadarStationPayload.TYPE,ClientboundCloseRadarStationPayload.STREAM_CODEC);PayloadTypeRegistry.serverboundPlay().register(ServerboundCloseRadarStationPayload.TYPE,ServerboundCloseRadarStationPayload.STREAM_CODEC);PayloadTypeRegistry.serverboundPlay().register(ServerboundConfigureRadarStationPayload.TYPE,ServerboundConfigureRadarStationPayload.STREAM_CODEC);ServerPlayNetworking.registerGlobalReceiver(ServerboundCloseRadarStationPayload.TYPE,(p,c)->VIEWERS.remove(c.player().getUUID()));ServerPlayNetworking.registerGlobalReceiver(ServerboundConfigureRadarStationPayload.TYPE,(p,c)->configure(c.player(),p));ServerPlayConnectionEvents.DISCONNECT.register((h,s)->VIEWERS.remove(h.getPlayer().getUUID()));registered=true;}public static void open(ServerPlayer player,RadarStationBlockEntity station){if(player.level()!=station.getLevel()||player.distanceToSqr(Vec3.atCenterOf(station.getBlockPos()))>64)return;VIEWERS.put(player.getUUID(),new Viewer(player,station.radarId(),station.getBlockPos()));ServerPlayNetworking.send(player,new ClientboundOpenRadarStationPayload(station.radarId(),station.getBlockPos(),player.level().dimension().identifier(),player.level().getGameTime(),RadarStationConstants.SWEEP_PERIOD_TICKS,RadarStationConstants.DETECTION_RANGE_BLOCKS,station.warningRadius(),station.phaseOffset()));sendState(station);if(!station.observations().isEmpty())sendObservations(station,List.copyOf(station.observations()));}public static void sendObservations(RadarStationBlockEntity station,List<RadarStationObservation>fresh){send(station,new ClientboundRadarStationObservationPayload(station.radarId(),fresh));}public static void sendState(RadarStationBlockEntity station){if(station.getLevel()instanceof net.minecraft.server.level.ServerLevel level)send(station,new ClientboundRadarStationStatePayload(station.radarId(),station.warningRadius(),station.warningActive(),station.observations().size(),station.threatCount(),level.getGameTime()));}private static void send(RadarStationBlockEntity station,net.minecraft.network.protocol.common.custom.CustomPacketPayload payload){VIEWERS.values().removeIf(v->{if(v.radarId.equals(station.radarId())){if(v.player.level()!=station.getLevel()||!station.getBlockPos().equals(v.centre)){ServerPlayNetworking.send(v.player,new ClientboundCloseRadarStationPayload(station.radarId()));return true;}ServerPlayNetworking.send(v.player,payload);}return false;});}public static void closeStation(UUID id){VIEWERS.values().removeIf(v->{if(v.radarId.equals(id)){ServerPlayNetworking.send(v.player,new ClientboundCloseRadarStationPayload(id));return true;}return false;});}private static void configure(ServerPlayer player,ServerboundConfigureRadarStationPayload p){Viewer v=VIEWERS.get(player.getUUID());if(v==null||!v.radarId.equals(p.radarId())||!v.centre.equals(p.centre())||!Double.isFinite(p.warningRadius())||player.distanceToSqr(Vec3.atCenterOf(p.centre()))>64)return;if(!(player.level().getBlockEntity(p.centre())instanceof RadarStationBlockEntity station)||!station.radarId().equals(p.radarId())||!RadarStationStructure.complete(player.level(),p.centre(),station.facing()))return;station.setWarningRadius(p.warningRadius());sendState(station);}private record Viewer(ServerPlayer player,UUID radarId,net.minecraft.core.BlockPos centre){}}